type Entity = { x: number; y: number; vx: number; vy: number };
function updateEntity(e: Entity, dt: number, bounds: { w: number; h: number }) {
  e.x = Math.max(0, Math.min(bounds.w, e.x + e.vx * dt));
  e.y = Math.max(0, Math.min(bounds.h, e.y + e.vy * dt));
}
```
